import json
import sys

count_by_type = {}
roles = {"user":0, "assistant":0, "toolResult":0}
tool_names = {}
agents_used = set()
errors_seen = 0
with open('/tmp/failure.jsonl') as f:
    for i, line in enumerate(f, 1):
        e = json.loads(line)
        t = e.get('type')
        count_by_type[t] = count_by_type.get(t, 0) + 1
        if t == 'message':
            msg = e.get('message', {})
            role = msg.get('role', '?')
            roles[role] = roles.get(role, 0) + 1
            if 'model' in e:
                agents_used.add(e.get('model'))
            content = msg.get('content', [])
            if isinstance(content, list):
                for c in content:
                    if isinstance(c, dict):
                        if c.get('type') == 'toolCall':
                            n = c.get('name', '?')
                            tool_names[n] = tool_names.get(n, 0) + 1
                        if c.get('type') == 'toolResult' and c.get('isError'):
                            errors_seen += 1
            if msg.get('role') == 'toolResult':
                if msg.get('isError'):
                    errors_seen += 1

print('Types:', count_by_type)
print('Roles:', roles)
print('Errors seen:', errors_seen)
print('Top tools used:')
for n, c in sorted(tool_names.items(), key=lambda x: -x[1]):
    print(f'  {n}: {c}')
EOF', 'description': 'Summarize the trajectory by event types and tools'}

